BEGIN TRANSACTION;
CREATE TABLE a(id TEXT PRIMARY KEY,rev INTEGER NOT NULL,body TEXT NOT NULL,live INTEGER NOT NULL,k TEXT,route TEXT,day TEXT,region TEXT,amount INTEGER,factor INTEGER);
CREATE TABLE b(id TEXT PRIMARY KEY,rev INTEGER NOT NULL,body TEXT NOT NULL,live INTEGER NOT NULL,k TEXT,route TEXT,day TEXT,region TEXT,amount INTEGER,factor INTEGER);
CREATE TABLE c(id TEXT PRIMARY KEY,rev INTEGER NOT NULL,body TEXT NOT NULL,live INTEGER NOT NULL,k TEXT,route TEXT,day TEXT,region TEXT,amount INTEGER,factor INTEGER);
CREATE TABLE g(token TEXT PRIMARY KEY,day TEXT,region TEXT,n INTEGER,valued INTEGER,total INTEGER,samples INTEGER);
CREATE TABLE j1(token TEXT PRIMARY KEY,aid TEXT,bid TEXT,k TEXT,route TEXT,day TEXT,region TEXT,amount INTEGER);
CREATE TABLE j2(token TEXT PRIMARY KEY,aid TEXT,bid TEXT,cid TEXT,k TEXT,route TEXT,day TEXT,region TEXT,amount INTEGER,factor INTEGER,charge INTEGER);
CREATE TABLE meta(n INTEGER NOT NULL);
CREATE TABLE receipts(id TEXT PRIMARY KEY,payload TEXT NOT NULL,result TEXT NOT NULL);
CREATE INDEX ix_a_k ON a(k);
CREATE INDEX ix_b_k ON b(k);
CREATE INDEX ix_c_route ON c(route);
CREATE INDEX ix_j1_k ON j1(k);
CREATE INDEX ix_j1_route ON j1(route);
CREATE INDEX ix_j2_route ON j2(route);
CREATE INDEX ix_j2_group ON j2(day,region);
COMMIT;
